import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        a = int(next(iterator))
        b = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    edges = []
    for _ in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        edges.append((u, v))

    adj_a = [[] for _ in range(a + 1)]
    adj_b = [[] for _ in range(b + 1)]

    for i, (u, v) in enumerate(edges):
        adj_a[u].append((v, i))
        adj_b[v].append((u, i))

    max_degree = 0
    deg_a = [0] * (a + 1)
    deg_b = [0] * (b + 1)

    for u in range(1, a + 1):
        deg_a[u] = len(adj_a[u])
        if deg_a[u] > max_degree:
            max_degree = deg_a[u]
    for v in range(1, b + 1):
        deg_b[v] = len(adj_b[v])
        if deg_b[v] > max_degree:
            max_degree = deg_b[v]

    c = max_degree if m > 0 else 0
    colors = [0] * m

    if m == 0:
        print(0)
        print()
        return

    queue = []
    in_queue = [False] * (a + 1)
    for u in range(1, a + 1):
        if deg_a[u] > 0:
            queue.append(u)
            in_queue[u] = True

    head = 0
    while head < len(queue):
        u = queue[head]
        head += 1

        used_colors = set()
        for v, idx in adj_a[u]:
            if colors[idx] != 0:
                used_colors.add(colors[idx])

        current_color = 1
        for v, idx in adj_a[u]:
            while current_color in used_colors:
                current_color += 1
            colors[idx] = current_color
            used_colors.add(current_color)

            deg_b[v] -= 1
            if deg_b[v] == 0:
                continue

            if not in_queue[v]:
                queue.append(v)
                in_queue[v] = True

    print(c)
    print(*(colors))

if __name__ == "__main__":
    main()
